static void heap_initialize(void)
{
    heap_head = (Block *)heap;
    heap_head->size = sizeof(heap) - sizeof(Block);
    heap_head->next = 0;
    heap_head->free = 1;
}

static size_t align_size(size_t n)
{
    return (n + 7U) & ~(size_t)7U;
