static void split_block(Block *block, size_t needed)
{
    if (block->size >= needed + sizeof(Block) + 16U) {
        Block *next = (Block *)((unsigned char *)(block + 1) + needed);
        next->size = block->size - needed - sizeof(Block);
        next->next = block->next;
        next->free = 1;
        block->next = next;
        block->size = needed;
    }
}

void *malloc(size_t size)
