    } else if (base == 0 && *p == '0') base = 8;
    else if (base == 0) base = 10;
    for (;;) {
        unsigned digit = 0xffffffffU;
        if (*p >= '0' && *p <= '9') digit = (unsigned)(*p - '0');
        else if (*p >= 'a' && *p <= 'f') digit = (unsigned)(*p - 'a' + 10);
