#include "vmrt.h"
#include <stdint.h>

static uint64_t multiply32(uint32_t a, uint32_t b)
{
    uint32_t high;
    uint32_t low;
    __asm__ ("multu %2, %3" : "=h"(high), "=l"(low) : "r"(a), "r"(b));
    return ((uint64_t)high << 32) | low;
}

uint64_t __muldi3(uint64_t a, uint64_t b)
{
    uint32_t a0 = (uint32_t)a;
    uint32_t a1 = (uint32_t)(a >> 32);
    uint32_t b0 = (uint32_t)b;
    uint32_t b1 = (uint32_t)(b >> 32);
    uint64_t low = multiply32(a0, b0);
    uint32_t cross = (uint32_t)multiply32(a0, b1) +
                     (uint32_t)multiply32(a1, b0);
    return low + ((uint64_t)cross << 32);
}

uint64_t __ashldi3(uint64_t value, int count)
{
    uint32_t low = (uint32_t)value;
    uint32_t high = (uint32_t)(value >> 32);
    uint32_t result_low;
    uint32_t result_high;
    if (count <= 0) return value;
    if (count >= 64) return 0;
    if (count < 32) {
        result_low = low << count;
        result_high = (high << count) | (low >> (32 - count));
    } else if (count == 32) {
        result_low = 0;
        result_high = low;
    } else {
        result_low = 0;
        result_high = low << (count - 32);
    }
    return ((uint64_t)result_high << 32) | result_low;
}

uint64_t __lshrdi3(uint64_t value, int count)
{
    uint32_t low = (uint32_t)value;
    uint32_t high = (uint32_t)(value >> 32);
    uint32_t result_low;
    uint32_t result_high;
    if (count <= 0) return value;
    if (count >= 64) return 0;
    if (count < 32) {
        result_low = (low >> count) | (high << (32 - count));
        result_high = high >> count;
    } else if (count == 32) {
        result_low = high;
        result_high = 0;
    } else {
        result_low = high >> (count - 32);
        result_high = 0;
    }
    return ((uint64_t)result_high << 32) | result_low;
}

int64_t __ashrdi3(int64_t value, int count)
{
    int32_t high = (int32_t)(uint32_t)((uint64_t)value >> 32);
    uint32_t low = (uint32_t)value;
    uint32_t result_low;
    int32_t result_high;
    if (count <= 0) return value;
    if (count >= 64) return high < 0 ? -1 : 0;
    if (count < 32) {
        result_low = (low >> count) | ((uint32_t)high << (32 - count));
        result_high = high >> count;
    } else if (count == 32) {
        result_low = (uint32_t)high;
        result_high = high;
    } else {
        result_low = (uint32_t)(high >> (count - 32));
        result_high = high >> (count - 32);
    }
    return (int64_t)(((uint64_t)(uint32_t)result_high << 32) | result_low);
}

static uint64_t unsigned_divmod(uint64_t dividend, uint64_t divisor,
                                uint64_t *remainder)
{
    uint64_t quotient = 0;
    uint64_t bit = 1;
    if (divisor == 0) {
        if (remainder) *remainder = dividend;
        return 0;
    }
    while (divisor <= (UINT64_MAX >> 1) && (divisor << 1) <= dividend) {
        divisor <<= 1;
        bit <<= 1;
    }
    while (bit != 0) {
        if (dividend >= divisor) {
            dividend -= divisor;
            quotient += bit;
        }
        divisor >>= 1;
        bit >>= 1;
    }
    if (remainder) *remainder = dividend;
    return quotient;
}

uint64_t __udivmoddi4(uint64_t dividend, uint64_t divisor, uint64_t *remainder)
{
    return unsigned_divmod(dividend, divisor, remainder);
}

uint64_t __udivdi3(uint64_t dividend, uint64_t divisor)
{
    return unsigned_divmod(dividend, divisor, 0);
}

uint64_t __umoddi3(uint64_t dividend, uint64_t divisor)
{
    uint64_t remainder;
    unsigned_divmod(dividend, divisor, &remainder);
    return remainder;
}

int64_t __divdi3(int64_t dividend, int64_t divisor)
{
    uint64_t quotient;
    uint64_t remainder;
    int negative = (dividend < 0) != (divisor < 0);
    uint64_t unsigned_dividend = dividend < 0
        ? (uint64_t)0 - (uint64_t)dividend
        : (uint64_t)dividend;
    uint64_t unsigned_divisor = divisor < 0
        ? (uint64_t)0 - (uint64_t)divisor
        : (uint64_t)divisor;
    quotient = unsigned_divmod(unsigned_dividend, unsigned_divisor, &remainder);
    if (negative) quotient = (uint64_t)0 - quotient;
    return (int64_t)quotient;
}

int64_t __moddi3(int64_t dividend, int64_t divisor)
{
    uint64_t remainder;
    int negative = dividend < 0;
    uint64_t unsigned_dividend = negative
        ? (uint64_t)0 - (uint64_t)dividend
        : (uint64_t)dividend;
    uint64_t unsigned_divisor = divisor < 0
        ? (uint64_t)0 - (uint64_t)divisor
        : (uint64_t)divisor;
    unsigned_divmod(unsigned_dividend, unsigned_divisor, &remainder);
    if (negative && remainder != 0) remainder = (uint64_t)0 - remainder;
    return (int64_t)remainder;
}
